<script>
 import {onDestroy} from 'svelte';
 let {resource,evidence=[],revision,request,onSaved,onDirtyChange=()=>{}}=$props();
 let captured=$state(null),purpose=$state(''),availability=$state('unknown'),permission=$state('unknown'),start=$state(''),end=$state(''),timeZone=$state('UTC'),notes=$state(''),evidenceIds=$state([]),intent=$state(null),busy=$state(false),unknown=$state(false),error=$state(''),notice=$state('');
 const dirty=$derived(Boolean(captured||intent));
 $effect(()=>onDirtyChange(dirty));
 onDestroy(()=>onDirtyChange(false));
 function edit(){captured||={id:resource.id};notice='';if(!unknown)intent=null;}
 function clear(){captured=null;purpose='';availability='unknown';permission='unknown';start='';end='';timeZone='UTC';notes='';evidenceIds=[];intent=null;error='';}
 async function save(){if(busy)return;if(!intent)intent={path:'/resources/'+encodeURIComponent(captured.id)+'/confirmation',body:{expectedRevision:revision,idempotencyKey:crypto.randomUUID(),confirmation:{purpose,availability,permission,start,end,timeZone,evidenceIds:[...evidenceIds],notes}}};busy=true;error='';try{await request(intent.path,{method:'POST',body:JSON.stringify(intent.body)});clear();unknown=false;notice='Planning details saved. Import records and earlier reports are unchanged.';await onSaved();}catch(failure){error=failure.message;unknown=!(Number.isInteger(failure.status)&&failure.status>=400&&failure.status<500);}finally{busy=false;}}
</script>
{#if resource||captured}<details class="resource-confirmation"><summary>Confirm planning details</summary><p>Manager-reported for this proposed use, not a booking or publication approval.</p>{#if captured&&captured.id!==resource?.id}<p>Your working confirmation stays attached to the original resource.</p>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
<fieldset disabled={busy||unknown}><label>Proposed use<input bind:value={purpose} oninput={edit} maxlength="500"/></label><label>Availability<select bind:value={availability} onchange={edit}><option value="unknown">Needs checking</option><option value="confirmed">I confirm the reported window</option><option value="unavailable">Unavailable</option></select></label><label>Start, including UTC offset<input bind:value={start} oninput={edit} placeholder="2026-10-20T10:00:00+01:00"/></label><label>End, including UTC offset<input bind:value={end} oninput={edit} placeholder="2026-10-20T18:00:00+01:00"/></label><label>Time zone<input bind:value={timeZone} oninput={edit} placeholder="Europe/London"/></label><label>Permission for this use<select bind:value={permission} onchange={edit}><option value="unknown">Needs checking</option><option value="confirmed">Reported permission confirmed</option><option value="denied">Permission denied</option></select></label><fieldset><legend>Supporting evidence</legend>{#each evidence as source(source.id)}<label><input type="checkbox" value={source.id} bind:group={evidenceIds} onchange={edit}/>{source.title}</label>{/each}</fieldset><label>Confirmation notes<textarea bind:value={notes} oninput={edit} maxlength="2000" rows="2"></textarea></label></fieldset>
{#if unknown}<p>The reply was interrupted. Check this same save before changing the confirmation.</p><button disabled={busy} onclick={save}>Retry same confirmation</button>{:else}{#if error}<button disabled={busy} onclick={async()=>{intent=null;await onSaved();}}>Reload current references</button>{/if}<button disabled={busy||!captured||!purpose.trim()} onclick={save}>Save planning confirmation</button>{/if}{#if dirty&&!unknown}<button disabled={busy} onclick={clear}>Clear working confirmation</button>{/if}</details>{/if}
<style>
.resource-confirmation{font-size:12px;margin:12px 0}.resource-confirmation summary{cursor:pointer;font-weight:600}.resource-confirmation label{display:block;margin:8px 0}.resource-confirmation input:not([type=checkbox]),select,textarea{display:block;width:100%;font:inherit;margin-top:4px}.resource-confirmation fieldset{border:0;padding:0;min-width:0}.resource-confirmation button{margin:8px 8px 0 0}
</style>
